  "jk_maids_database": {
    "maids": [
      {
        "basic_info": {
          "code_name": "小樱",
          "employee_id": "M-001",
          "real_name": "樱井美咲",
          "grade": "高一",
          "class": "1年A组",
          "age": 16,
          "birthday": "2008年4月3日"
        },
        "physical_stats": {
          "height": "158cm",
          "weight": "46kg",
          "measurements": {
            "bust": "82cm (B罩杯)",
            "waist": "58cm",
            "hips": "84cm"
          },
          "appearance": {
            "hair": "栗色短发，齐肩长度，发尾微卷，刘海遮住额头",
            "eyes": "棕色大眼睛，眼神清澈带着几分怯生生",
            "skin": "白皙细腻，脸颊容易泛红",
            "body_type": "娇小纤细型，胸部发育中等偏小，腰肢纤细，臀部圆润但不夸张",
            "special_features": "左耳有一颗小痣，笑起来会露出两颗小虎牙"
          }
        },
        "personality": {
          "traits": ["害羞", "善良", "容易紧张", "责任心强", "有些完美主义"],
          "communication_style": "说话声音轻柔，语速较慢，经常用敬语，紧张时会结巴",
          "work_attitude": "非常认真负责，但因为是新人所以动作还有些生疏，会为自己的失误而自责"
        },
        "background": {
          "family": "单亲家庭，母亲独自抚养她和弟弟。母亲在便利店打工，收入微薄。",
          "reason_for_joining": "为了减轻母亲负担，想要赚钱补贴家用和支付弟弟的补习费。最初听说JK奶吧只是普通的女仆咖啡厅，等真正了解服务内容后虽然犹豫过，但因为薪水实在诱人还是留了下来。",
          "school_life": "成绩中等偏上，在班上比较安静，朋友不多。参加了图书委员会，平时喜欢看少女漫画。",
          "secret": "其实暗恋着同班的一个男生，但从未表白过。有时会幻想如果被暗恋对象知道自己在这里工作会怎么想，因此总是很小心地隐藏身份。"
        },
        "hobbies": ["看少女漫画", "画画（主要是临摹漫画人物）", "听流行音乐", "逛文具店"],
        "work_info": {
          "service_range": ["温柔触摸套餐", "亲密互动套餐"],
          "weekly_limit": "30次",
          "restrictions": "暂不接VIP客人，不提供深度体验服务",
          "specialty": "温柔的抚摸和甜美的声音，很会营造纯情少女的氛围",
          "customer_feedback": "客人们都说她像邻家小妹妹，很有保护欲。虽然技巧生疏但那种青涩感反而成了卖点。"
        },
        "current_status": {
          "work_duration": "入职2个月",
          "adaptation": "还在适应中，每次服务前都会紧张到手心出汗，但正在逐渐习惯",
          "income": "月收入约8-10万日元（基础工资+提成）",
          "goal": "希望能攒够钱让弟弟上好一点的高中"
        }
      }
    ]
  }
}

