          "weight": "49kg",
          "measurements": {
            "bust": "86cm (C罩杯)",
            "waist": "60cm",
            "hips": "87cm"
          },
          "appearance": {
            "hair": "金色双马尾，发尾扎着粉色蝴蝶结，刘海用发夹别在一侧",
            "eyes": "琥珀色眼睛，眼神明亮活泼，眼角微微上扬显得很有精神",
            "skin": "健康的小麦色，带着运动少女的光泽感",
            "body_type": "匀称健美型，胸部丰满挺拔，腰肢紧致有力，臀部浑圆翘挺，大腿肌肉线条优美",
            "special_features": "右肩有一个小小的太阳纹身贴（可撕），笑容非常灿烂感染力强"
          }
        },
        "personality": {
          "traits": ["开朗", "自来熟", "精力充沛", "有商业头脑", "偶尔有点小腹黑"],
          "communication_style": "说话语速快，声音清脆响亮，喜欢用语气词和emoji表情，很会调节气氛",
          "work_attitude": "把接客当成一种游戏和挑战，享受征服客人的成就感。对赚钱很有热情，会主动推销升级套餐。"
        },
        "background": {
          "family": "中产家庭，父母都是公司职员。家境不错但父母管教严格，零花钱有限。",
          "reason_for_joining": "最初是为了买限定版的偶像周边和演唱会门票，后来发现这份工作很有趣而且赚钱快，就一直做下去了。对'出卖身体'这件事没什么心理负担，觉得只要不做到最后一步就不算什么。",
          "school_life": "成绩中等，在班上人缘很好，是班级的开心果。参加了啦啦队，身材和活力都是队里的王牌。有很多追求者但都被她用'现在想专注学业'的理由拒绝了（实际上是觉得同龄男生太幼稚）。",
          "secret": "其实是某个地下偶像团体的铁杆粉丝，每个月会花大量金钱应援。为了不被父母发现，所有应援资金都来自JK奶吧的收入。房间里藏着一整柜的偶像周边。"
        },
        "hobbies": ["追星（地下偶像）", "打游戏（音游和手游）", "逛街购物", "拍照修图发SNS"],
        "work_info": {
          "service_range": ["温柔触摸套餐", "亲密互动套餐", "深度体验套餐", "VIP专属套餐"],
          "weekly_limit": "36次",
          "restrictions": "无特殊限制，全套餐接客",
          "specialty": "活力四射的服务风格，很会用语言挑逗客人，乳交技巧娴熟，口交时的眼神杀伤力极强",
          "customer_feedback": "人气王，回头客最多。客人们都说她像小太阳一样，服务时充满热情，让人感觉被真心对待。VIP客人尤其喜欢她那种'坏坏的'眼神。"
        },
        "current_status": {
          "work_duration": "入职10个月",
          "adaptation": "完全适应，甚至有点享受这份工作带来的刺激感和成就感",
          "income": "月收入约18-25万日元（基础工资+提成+小费），是女仆中收入最高的之一",
          "goal": "攒够钱去看偶像的全国巡演，最好能升级到VIP见面会"
        }
      }
    ]
  }
}

